  "root_causes": [
    {
      "service": "recommendation",
      "fault_kind": "pod_unavailable",
      "evidence": [
        {"kind": "metric", "sql": "SELECT time, metric, attr_k8s_pod_name, value FROM abnormal_metrics WHERE attr_k8s_pod_name = 'recommendation-79b9d89bfc-zkskw' AND metric = 'k8s.container.ready' ORDER BY time", "claim": "Recommendation pod reports container ready=0 from 02:50:25 through the end of the window, versus ready=1 in normal."},
        {"kind": "trace", "sql": "SELECT span_name, attr_status_code, count(*) AS n, avg(duration)/1e6 AS avg_ms FROM abnormal_traces WHERE service_name = 'frontend' AND span_name LIKE 'recommendation.%' GROUP BY 1,2", "claim": "All 380 frontend calls to recommendation.GetRecommendations end in Error, averaging about 0.01 ms."},
        {"kind": "trace", "sql": "SELECT count(*) AS n FROM abnormal_traces WHERE service_name = 'recommendation'", "claim": "Recommendation emits zero spans in the abnormal window, versus 348 in the normal window."},
        {"kind": "log", "sql": "SELECT service_name, level, message, count(*) AS n FROM abnormal_logs WHERE level = 'ERROR' GROUP BY 1,2,3", "claim": "Frontend logs 437 ERROR entries 'Recommendation service failed'; no other service logs errors."}
      ]
    }
